3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededException;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Rejects a create-owner request once 100 or more owners have already been registered on the
12	 * business day this owner will land on (by {@code registrationDate}). Runs before
13	 * {@link BuildOwner}, using the same effective registration date it will store — the date
14	 * supplied on the request, or the server date when omitted — rolled forward to a business day
15	 * (see {@link BusinessDay}). It counts existing owners whose registration date equals that
16	 * business day; at the limit the request is rejected 429 via {@link DailyLimitExceededException}.
17	 */
18	public class RejectDailyLimit {
19	
20	    private static final int DAILY_LIMIT = 100;
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DailyLimitExceededException {
24	        LocalDate effective = request.getRegistrationDate() != null ? request.getRegistrationDate() : LocalDate.now();
25	        LocalDate businessDay = BusinessDay.roll(effective);
26	        long count = ownerRepository.findAll().stream()
27	                .filter(o -> businessDay.equals(o.getRegistrationDate()))
28	                .count();
29	        if (count >= DAILY_LIMIT) {
30	            throw new DailyLimitExceededException(
31	                    "The maximum number of owners for today has already been reached");
32	        }
33	    }
34	}
