1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * First step of {@code POST /api/owners}: rejects a body that is missing or blank in any
13	 * required field (firstName, lastName, address, city, telephone) before {@link BuildOwner}
14	 * runs, so such a request is a 400 listing the offending fields rather than a persisted owner.
15	 *
16	 * <p>Reads the raw body (no {@code @Valid}) so this check runs ahead of bean validation and
17	 * owns the response format; the body is republished for later steps.
18	 *
19	 * <p>The address is normalized in place first (see {@link OwnerAddress}) so the required check
20	 * rejects an address that is blank <em>after</em> normalization, and every later step sees — and
21	 * the response returns — the normalized, composed address. An owner is valid when it supplies an
22	 * address in EITHER form: a non-blank structured {@code addressLine1} or the flat {@code address}.
23	 */
24	public class RequireOwnerFields {
25	
26	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
27	            throws MissingOwnerFieldsException {
28	        OwnerAddress.normalizeInPlace(request);
29	        List<String> missing = new ArrayList<>();
30	        if (isBlank(request.getFirstName())) {
31	            missing.add("firstName");
32	        }
33	        if (isBlank(request.getLastName())) {
34	            missing.add("lastName");
35	        }
36	        if (!OwnerAddress.hasAddress(request)) {
37	            missing.add("address");
38	        }
39	        if (isBlank(request.getCity())) {
40	            missing.add("city");
41	        }
42	        if (isBlank(request.getTelephone())) {
43	            missing.add("telephone");
44	        }
45	        if (!missing.isEmpty()) {
46	            throw new MissingOwnerFieldsException(missing);
