7	/**
8	 * Validates an owner's postcode WHEN PRESENT. A postcode is optional: an absent (null)
9	 * postcode passes untouched, keeping the request contract backward-compatible. When
10	 * present it must be a 4-digit code and, if the city has a known region, fall within that
11	 * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city
12	 * with no known region accepts any 4-digit postcode. Anything else is rejected 400 via
13	 * {@link InvalidPostcodeException}.
14	 */
15	public class ValidatePostcode {
16	
17	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
18	        String postcode = request.getPostcode();
19	        if (postcode == null) {
20	            return; // optional when absent
21	        }
22	        if (!postcode.matches("^[0-9]{4}$")) {
23	            throw new InvalidPostcodeException("Postcode must be a 4-digit code");
24	        }
25	        // Region reference data lives once in OwnerMemberId; share it rather than copy it.
26	        String region = OwnerMemberId.regionForCity(request.getCity());
27	        int[] range = region == null ? null : OwnerMemberId.postcodeRange(region);
28	        if (range == null) {
29	            return; // city with no known region accepts any 4-digit postcode
30	        }
31	        int value = Integer.parseInt(postcode);
32	        if (value < range[0] || value > range[1]) {
33	            throw new InvalidPostcodeException(
34	                    "Postcode " + postcode + " is not valid for city " + request.getCity());
35	        }
36	    }
37	}
