2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Rejects a create-owner request whose {@link OwnerIdentity#key(Owner) identity key} already
11	 * belongs to an existing owner. The key consolidates all duplicate detection — it is the
12	 * SHA-256 digest of {@code normalizedTelephone + '|' + email + '|' + soundex(lastName)} — so a
13	 * new owner collides only when its telephone, email <em>and</em> phonetic last name all match
14	 * an existing owner's. Because the telephone is part of the key, two owners sharing a last name
15	 * (phonetically) and postcode but carrying different telephones have different keys and are both
16	 * allowed; the later {@link AssignPossibleDuplicate} step merely flags the second as a soft
17	 * duplicate.
18	 *
19	 * <p>{@code sharesHousehold} bypasses this block outright: the caller is declaring the owner a
20	 * genuine additional member of that household, so the create is allowed regardless.
21	 *
22	 * <p>Runs within the create transaction but before {@link SaveOwner}, so the new owner is not
23	 * yet persisted and cannot collide with itself.
24	 */
25	public class RejectDuplicateIdentity {
26	
27	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
28	            throws DuplicateIdentityException {
29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            return; // declared household member — bypass the duplicate block
31	        }
32	        String key = OwnerIdentity.key(owner);
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (owner.getId() != null && owner.getId().equals(existing.getId())) {
35	                continue;
36	            }
37	            if (existing.isDeleted()) {
38	                continue; // a soft-deleted owner does not block a new identity
39	            }
40	            if (key.equals(OwnerIdentity.key(existing))) {
41	                throw new DuplicateIdentityException(
42	                        "Another owner with the same identity already exists");
43	            }
44	        }
45	    }
46	}
