package org.springframework.samples.petclinic.acceptance;

import org.junit.jupiter.api.Test;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import org.hamcrest.Matchers;
import tools.jackson.databind.node.ObjectNode;

/** TEMP verification: 400, 409 and 429 rejections all return RFC7807 problem+json
 *  with type/title/status/detail. */
class ProblemJsonVerifyTest extends AcceptanceBase {

	private void assertProblem(org.springframework.test.web.servlet.ResultActions ra, int code) throws Exception {
		ra.andExpect(content().contentTypeCompatibleWith("application/problem+json"))
				.andExpect(jsonPath("$.type").exists())
				.andExpect(jsonPath("$.title").exists())
				.andExpect(jsonPath("$.status").value(code))
				.andExpect(jsonPath("$.detail").exists());
	}

	@Test
	void badRequest400() throws Exception {
		ObjectNode o = knownOwner("Sydney");
		o.put("postcode", "9999"); // out of NSW range -> InvalidPostcodeException 400
		assertProblem(createOwner(o).andExpect(status().isBadRequest()), 400);
	}

	@Test
	void missingFields400() throws Exception {
		ObjectNode o = structuredOwner();
		o.remove("city");
		assertProblem(createOwner(o).andExpect(status().isBadRequest()), 400)
				.andExpect(jsonPath("$.errors").isArray());
	}

	@Test
	void conflict409() throws Exception {
		String city = "Town-cap-" + seq();
		fillCity(city, 50); // reach city capacity
		ObjectNode o = ownerNode();
		o.put("city", city);
		assertProblem(createOwner(o).andExpect(status().isConflict()), 409);
	}

	@Test
	void tooManyRequests429() throws Exception {
		createMany(100); // reach daily limit
		assertProblem(createOwner(ownerNode()).andExpect(status().isTooManyRequests()), 429);
	}
}

